import re
from typing import List, Dict, Any, Tuple, Optional

# Helpers are assumed to be available in the environment:
# node_by_title(doc, title), node_by_id(doc, node_id), children(doc, node),
# table_rows(node)

def _parse_objects(node: Dict[str, Any]) -> List[Dict[str, str]]:
    """Parse the Objects list node and return entity descriptors."""
    result = []
    pattern = re.compile(r"Object (\d+): (.+?) \(")
    for line in node.get("lines", []):
        m = pattern.match(line)
        if not m:
            # The line might not match the pattern; skip it
            continue
        obj_id, description = m.group(1), m.group(2)
        result.append({"id": obj_id, "description": description.strip()})
    return result

def _object_id_from_desc(desc: str) -> str:
    """Extract object numeric id from a string like '1 cyan rubber sphere'."""
    m = re.match(r"(\d+)", desc.strip())
    return m.group(1) if m else ""

def _parse_events(node: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Parse the Events list node and return a list of event dicts."""
    events = []
    for idx, line in enumerate(node.get("lines", [])):
        # Skip empty lines
        if not line.strip():
            continue
        # Identify frame number
        m_frame = re.match(r"Frame (\d+):", line)
        if not m_frame:
            continue
        frame = int(m_frame.group(1))
        # Simple regex for actions
        if "enters the scene" in line:
            m_obj = re.search(r"Object (\d+)", line)
            if m_obj:
                obj_id = m_obj.group(1)
                events.append({
                    "id": f"enter-{obj_id}-{frame}",
                    "time": frame,
                    "kind": "enter",
                    "entities": [obj_id],
                    "src": [node_by_id(doc, node["node_id"]), idx],
                })
        elif "exits the scene" in line:
            m_obj = re.search(r"Object (\d+)", line)
            if m_obj:
                obj_id = m_obj.group(1)
                events.append({
                    "id": f"exit-{obj_id}-{frame}",
                    "time": frame,
                    "kind": "exit",
                    "entities": [obj_id],
                    "src": [node_by_id(doc, node["node_id"]), idx],
                })
        elif "collides with" in line:
            m_objs = re.findall(r"Object (\d+)", line)
            if len(m_objs) == 2:
                e_id = f"collision-{m_objs[0]}-{m_objs[1]}-{frame}"
                events.append({
                    "id": e_id,
                    "time": frame,
                    "kind": "collision",
                    "entities": list(sorted(set(m_objs))),
                    "src": [node_by_id(doc, node["node_id"]), idx],
                })
        elif "is in view" in line:
            m_obj = re.search(r"Object (\d+)", line)
            if m_obj:
                obj_id = m_obj.group(1)
                events.append({
                    "id": f"present-{obj_id}-{frame}",
                    "time": frame,
                    "kind": "present",
                    "entities": [obj_id],
                    "src": [node_by_id(doc, node["node_id"]), idx],
                })
    return events

def _parse_motion_log(node: Dict[str, Any]) -> Dict[Tuple[str, int], Dict[str, Any]]:
    """Parse the Motion log table node into a mapping keyed by (obj_id, frame)."""
    data = {}
    for row_index, row in table_rows(node):
        frame = int(row.get("frame", 0))
        obj_desc = row.get("object", "")
        obj_id = _object_id_from_desc(obj_desc)
        # Convert numeric fields
        fields = {}
        for key in ["x", "y", "vx", "vy", "speed"]:
            val = row.get(key, "")
            try:
                fields[key] = float(val) if val else None
            except ValueError:
                fields[key] = None
        data[(obj_id, frame)] = {"time": frame, "fields": fields, "src": [node_by_id(doc, node["node_id"]), row_index]}
    return data

def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return list of entities in the given scope."""
    scope_node = node_by_title(doc, scope)
    # Find Objects node
    objs_node = next((c for c in children(doc, scope_node)
                     if c.get("kind") == "list" and c.get("title").startswith("Objects")), None)
    if not objs_node:
        return []
    return _parse_objects(objs_node)

def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last recorded time point (frame) in the scope."""
    scope_node = node_by_title(doc, scope)
    log_node = next((c for c in children(doc, scope_node)
                     if c.get("kind") == "table" and c.get("title").startswith("Motion log")), None)
    if not log_node:
        return None
    max_frame = -1
    for _, row in table_rows(log_node):
        try:
            f = int(row.get("frame", -1))
            if f > max_frame:
                max_frame = f
        except ValueError:
            continue
    return float(max_frame) if max_frame >= 0 else None

