def _parse_objects(node: Dict[str, Any]) -> List[Dict[str, str]]:
    """
    Parse a list node titled '<Video #: Objects>' to extract entity descriptions.
    Returns a list of dicts: {"id": str, "description": str}
    """
    result = []
    # Each line has form: 'Object <id>: <desc> ( ... )'
    for line in node.get("lines", []):
        m = re.match(r"Object\s+(\d+):\s+(.+?)\s*\(", line)
        if m:
            obj_id, desc = m.group(1), m.group(2).strip()
            result.append({"id": obj_id, "description": desc})
    return result

def _parse_events(node: Dict[str, Any]) -> List[Dict[str, Any]]:
    """
    Parse the events list node. Returns a list of event dicts:
        {"id": str, "time": int, "kind": str, "entities": [ids], "src": [node_id, line_index]}
    """
    events = []
    node_id = node["node_id"]
    for idx, line in enumerate(node.get("lines", [])):
        if not line.strip():
            continue
        m_frame = re.match(r"Frame\s+(\d+):", line)
        if not m_frame:
            continue
        frame = int(m_frame.group(1))
        # Determine type of event
        if "enters the scene" in line:
            m = re.search(r"Object\s+(\d+)", line)
            if m:
                obj_id = m.group(1)
                events.append({
                    "id": f"enter_{obj_id}_{frame}",
                    "time": frame,
                    "kind": "enter",
                    "entities": [obj_id],
                    "src": [node_id, idx]
