                obj_id = m.group(1)
                events.append({
                    "id": f"exit_{obj_id}_{frame}",
                    "time": frame,
                    "kind": "exit",
                    "entities": [obj_id],
                    "src": [node_id, idx]
                })
        elif "collides with" in line:
            objs = re.findall(r"Object\s+(\d+)", line)
            if len(objs) == 2:
                # Ensure sorted for consistency
                ent = sorted(objs)
                events.append({
                    "id": f"collision_{ent[0]}_{ent[1]}_{frame}",
                    "time": frame,
                    "kind": "collision",
                    "entities": ent,
                    "src": [node_id, idx]
                })
        elif "in view" in line:
            m = re.search(r"Object\s+(\d+)", line)
            if m:
                obj_id = m.group(1)
                events.append({
                    "id": f"present_{obj_id}_{frame}",
                    "time": frame,
                    "kind": "present",
                    "entities": [obj_id],
                    "src": [node_id, idx]
                })
    return events

def _parse_motion_log(node: Dict[str, Any]) -> Dict[Tuple[str, int], Dict[str, Any]]:
