import re
from typing import List, Dict, Any, Optional, Tuple

# ----------------------------------------------------------------------
# Helpers from the execution environment
# ----------------------------------------------------------------------
# node_by_title(doc, title)
# node_by_id(doc, node_id)
# children(doc, node)
# table_rows(node) -> iterator of (row_index, {column: cell})

# ----------------------------------------------------------------------
# Internal parsing helpers
# ----------------------------------------------------------------------
def _extract_object_id(desc: str) -> str:
    """Get numeric id from '1 cyan rubber sphere'."""
    m = re.match(r"^(\d+)", desc.strip())
    return m.group(1) if m else ""

def _parse_objects(node: Dict[str, Any]) -> List[Dict[str, str]]:
    """Parse 'Video #: Objects' list."""
    objs: List[Dict[str, str]] = []
    for line in node.get("lines", []):
        m = re.match(r"Object\s+(\d+):\s+(.+?)\s*\(", line)
        if m:
            obj_id, desc = m.group(1), m.group(2).strip()
            objs.append({"id": obj_id, "description": desc})
    return objs

def _parse_events(node: Dict[str, Any]) -> List[Dict[str, Any]]:
    """Parse 'Video #: Events' list."""
    events: List[Dict[str, Any]] = []
    node_id = node["node_id"]
    for line_index, line in enumerate(node.get("lines", [])):
        if not line.strip():
            continue
        m_frame = re.match(r"Frame\s+(\d+):", line)
        if not m_frame:
            continue
        frame = int(m_frame.group(1))
        kind: str | None = None
        ent_ids: List[str] = []
        if "enters the scene" in line:
            m = re.search(r"Object\s+(\d+)", line)
            if m:
                kind = "enter"
                ent_ids = [m.group(1)]
        elif "exits the scene" in line:
            m = re.search(r"Object\s+(\d+)", line)
            if m:
                kind = "exit"
                ent_ids = [m.group(1)]
        elif "collides with" in line:
            objs = re.findall(r"Object\s+(\d+)", line)
            if len(objs) == 2:
                kind = "collision"
                ent_ids = sorted(objs)
        elif "is in view" in line or "in view" in line or "view" in line:
            m = re.search(r"Object\s+(\d+)", line)
            if m:
                kind = "present"
                ent_ids = [m.group(1)]
        if kind:
            events.append({
                "id": f"{kind}_{'_'.join(ent_ids)}_{frame}",
                "time": frame,
                "kind": kind,
                "entities": ent_ids,
                "src": [node_id, line_index]
            })
    return events

def _parse_motion_log(node: Dict[str, Any]) -> Dict[Tuple[str, int], Dict[str, Any]]:
    """Parse Motion log table into a dict keyed by (object_id, frame)."""
    data: Dict[Tuple[str, int], Dict[str, Any]] = {}
    node_id = node["node_id"]
    for row_index, row in table_rows(node):
        try:
            frame = int(row.get("frame", -1))
        except ValueError:
            continue
        obj_desc = row.get("object", "")
        obj_id = _extract_object_id(obj_desc)
        if not obj_id:
            continue
        fields: Dict[str, Any] = {}
        for k in ("x", "y", "vx", "vy", "speed"):
            v = row.get(k, "")
            try:
                fields[k] = float(v) if v != "" else None
            except (ValueError, TypeError):
                fields[k] = None
        data[(obj_id, frame)] = {"time": frame, "fields": fields, "src": [node_id, row_index]}
    return data

# ----------------------------------------------------------------------
# Public API
# ----------------------------------------------------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, str]]:
    """Return all entities described in a scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith("Objects"):
            return _parse_objects(child)
    return []

def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return last frame recorded in the scope, or None if no motion log."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return None
    for child in children(doc, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith("Motion log"):
            max_frame = -1
            for _, row in table_rows(child):
                try:
                    f = int(row.get("frame", -1))
                except ValueError:
                    continue
                max_frame = max(max_frame, f)
            return float(max_frame) if max_frame >= 0 else None
    return None

def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return external inputs for the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    # Gather objects for validation
    obj_map: Dict[str, Dict[str, str]] = {e["id"]: e for e in entities(doc, scope)}

    # Motion data for states
    motion: Dict[Tuple[str, int], Dict[str, Any]] = {}
    for child in children(doc, scope_node):
        if child.get("kind") == "table" and child.get("title", "").endswith("Motion log"):
            motion = _parse_motion_log(child)
            break

    inputs_list: List[Dict[str, Any]] = []
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith("Events"):
            for ev in _parse_events(child):
                if ev["kind"] in ("enter", "present"):
                    obj_id = ev["entities"][0]
                    if obj_id not in obj_map:
                        continue
                    state = motion.get((obj_id, ev["time"]), {})
                    fields = state.get("fields", {})
                    inputs_list.append({
                        "id": ev["id"],
                        "time": float(ev["time"]),
                        "kind": ev["kind"],
                        "entities": [obj_id],
                        "fields": fields,
                        "src": ev["src"]
                    })
    return inputs_list

def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return outcomes produced within the scope."""
    scope_node = node_by_title(doc, scope)
    if not scope_node:
        return []

    outcomes_list: List[Dict[str, Any]] = []
    for child in children(doc, scope_node):
        if child.get("kind") == "list" and child.get("title", "").endswith("Events"):
            for ev in _parse_events(child):
                if ev["kind"] in ("enter", "present"):
                    continue  # inputs
                outcomes_list.append({
                    "time": float(ev["time"]),
                    "kind": ev["kind"],
                    "entities": ev["entities"],
                    "value": None,
                    "src": ev["src"]
                })
    return outcomes_list

def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return any constants defined in the scope (none in this document)."""
    return {}
